/**
 * Converts between Roman numerals and integers
 * @param {string|number} input - Roman numeral string or integer to convert
 * @returns {number|string} - Integer if input is Roman numeral, Roman numeral if input is integer
 */
function paginate_results(input) {
  if (typeof input === 'string') {
    return romanToInt(input);
  } else if (typeof input === 'number' && Number.isInteger(input) && input > 0) {
    return intToRoman(input);
  } else {
    throw new Error('Input must be a Roman numeral string or positive integer');
  }
}

/**
 * Converts Roman numeral to integer
 * @param {string} roman - Roman numeral string
 * @returns {number} - Integer value
 */
function romanToInt(roman) {
  if (typeof roman !== 'string' || roman.length === 0) {
    throw new Error('Invalid Roman numeral: must be a non-empty string');
  }

  const romanValues = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  // Check for valid characters
  const validChars = /^[IVXLCDM]+$/;
  if (!validChars.test(roman.toUpperCase())) {
    throw new Error('Invalid Roman numeral: contains invalid characters');
  }

  const upperRoman = roman.toUpperCase();
  let result = 0;
  let prevValue = 0;

  // Process from right to left
  for (let i = upperRoman.length - 1; i >= 0; i--) {
    const currentValue = romanValues[upperRoman[i]];

    // If current value is less than previous value, subtract it (e.g., IV = 4)
    if (currentValue < prevValue) {
      result -= currentValue;
    } else {
      result += currentValue;
    }

    prevValue = currentValue;
  }

  // Validate the result by converting back and checking
  if (intToRoman(result) !== upperRoman) {
    throw new Error('Invalid Roman numeral format');
  }

  return result;
}

/**
 * Converts integer to Roman numeral
 * @param {number} num - Integer to convert (1-3999)
 * @returns {string} - Roman numeral string
 */
function intToRoman(num) {
  if (!Number.isInteger(num) || num <= 0 || num > 3999) {
    throw new Error('Number must be an integer between 1 and 3999');
  }

  const values = [
    [1000, 'M'],
    [900, 'CM'],
    [500, 'D'],
    [400, 'CD'],
    [100, 'C'],
    [90, 'XC'],
    [50, 'L'],
    [40, 'XL'],
    [10, 'X'],
    [9, 'IX'],
    [5, 'V'],
    [4, 'IV'],
    [1, 'I']
  ];

  let result = '';
  let remaining = num;

  for (const [value, symbol] of values) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

// Test cases
function runTests() {
  console.log('Running Roman Numeral Converter Tests...\n');

  // Test Roman to Integer conversions
  console.log('=== Roman to Integer Tests ===');
  const romanToIntTests = [
    ['I', 1],
    ['V', 5],
    ['X', 10],
    ['L', 50],
    ['C', 100],
    ['D', 500],
    ['M', 1000],
    ['III', 3],
    ['IV', 4],
    ['VI', 6],
    ['IX', 9],
    ['XI', 11],
    ['XL', 40],
    ['XC', 90],
    ['CD', 400],
    ['CM', 900],
    ['XLII', 42],
    ['XCIX', 99],
    ['CDXLIV', 444],
    ['CMXCIX', 999],
    ['MCMXCIV', 1994],
    ['MMXXIII', 2023],
    ['MMMCMXCIX', 3999]
  ];

  let passed = 0;
  let failed = 0;

  romanToIntTests.forEach(([roman, expected]) => {
    try {
      const result = paginate_results(roman);
      if (result === expected) {
        console.log(`✓ ${roman} = ${result}`);
        passed++;
      } else {
        console.log(`✗ ${roman}: expected ${expected}, got ${result}`);
        failed++;
      }
    } catch (error) {
      console.log(`✗ ${roman}: Error - ${error.message}`);
      failed++;
    }
  });

  // Test Integer to Roman conversions
  console.log('\n=== Integer to Roman Tests ===');
  const intToRomanTests = [
    [1, 'I'],
    [4, 'IV'],
    [5, 'V'],
    [9, 'IX'],
    [10, 'X'],
    [14, 'XIV'],
    [19, 'XIX'],
    [40, 'XL'],
    [42, 'XLII'],
    [50, 'L'],
    [90, 'XC'],
    [99, 'XCIX'],
    [100, 'C'],
    [400, 'CD'],
    [444, 'CDXLIV'],
    [500, 'D'],
    [900, 'CM'],
    [999, 'CMXCIX'],
    [1000, 'M'],
    [1994, 'MCMXCIV'],
    [2023, 'MMXXIII'],
    [3999, 'MMMCMXCIX']
  ];

  intToRomanTests.forEach(([num, expected]) => {
    try {
      const result = paginate_results(num);
      if (result === expected) {
        console.log(`✓ ${num} = ${result}`);
        passed++;
      } else {
        console.log(`✗ ${num}: expected ${expected}, got ${result}`);
        failed++;
      }
    } catch (error) {
      console.log(`✗ ${num}: Error - ${error.message}`);
      failed++;
    }
  });

  // Test edge cases and error handling
  console.log('\n=== Edge Case and Error Tests ===');

  // Test lowercase input
  try {
    const result = paginate_results('iv');
    console.log(`✓ Lowercase 'iv' = ${result} (should be 4)`);
    passed++;
  } catch (error) {
    console.log(`✗ Lowercase test failed: ${error.message}`);
    failed++;
  }

  // Test invalid Roman numeral
  try {
    paginate_results('IIII');
    console.log('✗ Should have thrown error for IIII');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected 'IIII': ${error.message}`);
    passed++;
  }

  // Test invalid characters
  try {
    paginate_results('ABC');
    console.log('✗ Should have thrown error for ABC');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected 'ABC': ${error.message}`);
    passed++;
  }

  // Test out of range numbers
  try {
    paginate_results(0);
    console.log('✗ Should have thrown error for 0');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected 0: ${error.message}`);
    passed++;
  }

  try {
    paginate_results(4000);
    console.log('✗ Should have thrown error for 4000');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected 4000: ${error.message}`);
    passed++;
  }

  try {
    paginate_results(-5);
    console.log('✗ Should have thrown error for -5');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected -5: ${error.message}`);
    passed++;
  }

  // Test empty string
  try {
    paginate_results('');
    console.log('✗ Should have thrown error for empty string');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected empty string: ${error.message}`);
    passed++;
  }

  // Test non-integer input
  try {
    paginate_results(3.14);
    console.log('✗ Should have thrown error for 3.14');
    failed++;
  } catch (error) {
    console.log(`✓ Correctly rejected 3.14: ${error.message}`);
    passed++;
  }

  console.log(`\n=== Test Results ===`);
  console.log(`Total tests: ${passed + failed}`);
  console.log(`Passed: ${passed}`);
  console.log(`Failed: ${failed}`);

  return failed === 0;
}

// Run tests if this file is executed directly
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { paginate_results, romanToInt, intToRoman };
  // Run tests if not in test environment
  if (require.main === module) {
    runTests();
  }
} else {
  // Browser environment
  runTests();
}
